using PhotoTrail.Windows;
using System.Text.Json;
static class RenameSequenceChecks
{
 public static async Task RunAsync()
 {
  int count=0;void Check(bool value,string why){if(!value)throw new Exception("R08b: "+why);count++;}
  RenameRule Rule(string action)=>new("action"){Action=action};string Name(RenameRule r,int index=0)=>RenamePlan.Apply("old.jpg",[r],index);
  void Reject(Action action,string why){try{action();throw new Exception("accepted: "+why);}catch(Exception e)when(e is ArgumentException or IOException or InvalidDataException or JsonException or KeyNotFoundException){Check(true,why);}}
  foreach(var (action,expected) in new[]{("number-set","007.jpg"),("number-begin","007old.jpg"),("number-end","old007.jpg"),("number-before","007old.jpg"),("number-after","old007.jpg"),("number-position","007old.jpg")})Check(Name(Rule(action) with{Start=3,Step=2,Anchor="old"},2)==expected,action);
  Check(Name(Rule("number-set") with{Start=-3,Step=-2,Padding=2},1)=="-05.jpg","explicit negative numbers no unsigned truncation");
  Check(Name(Rule("number-set") with{Start=long.MaxValue,Padding=3})==long.MaxValue+".jpg","full64bit retained beyond padding");Reject(()=>Name(Rule("number-set") with{Start=long.MaxValue},1),"overflow refused");
  foreach(var (number,letters) in new[]{(1L,"A"),(26L,"Z"),(27L,"AA"),(52L,"AZ"),(53L,"BA"),(702L,"ZZ"),(703L,"AAA"),(1_000_000_000L,"CFDGSXL")}){var actual=RenameTransform.Alphabet(number);Check(actual==letters,"alphabet conversion "+number);Check(RenameTransform.AlphabetIndex(actual)==number,"alphabet reversible "+number);}
  foreach(var invalid in new[]{0L,-1L,1_000_000_001L})Reject(()=>RenameTransform.Alphabet(invalid),"alphabet range");
  foreach(var invalid in new[]{"","1","A_","中","ZZZZZZZ"})Reject(()=>RenameTransform.AlphabetIndex(invalid),"alphabet seed");
  Check(Name(Rule("alphabet-set") with{AlphabetStart="z"},1)=="aa.jpg","alphabet lower rollover");Check(Name(Rule("alphabet-set") with{AlphabetStart="Z",AlphabetWidth=3})=="AAZ.jpg","alphabet width source semantics");
  foreach(var (number,roman) in new[]{(1L,"I"),(4L,"IV"),(9L,"IX"),(40L,"XL"),(90L,"XC"),(400L,"CD"),(900L,"CM"),(3999L,"MMMCMXCIX")})Check(RenameTransform.Roman(number)==roman,"roman "+number);
  foreach(var invalid in new[]{0L,-1L,4000L})Reject(()=>RenameTransform.Roman(invalid),"roman range");Check(Name(Rule("roman-set") with{Start=9,CaseSensitive=false})=="ix.jpg","roman case");
  var operation=Rule("number-change") with{NumberOperation="subtract",NumberValue=15,Padding=2};Check(RenamePlan.Apply("a10_b20.jpg",[operation],0)=="a-05_b05.jpg","arithmetic sign/width/all");Check(RenamePlan.Apply("a10_b20.jpg",[operation with{Occurrence="last"}],0)=="a10_b05.jpg","arithmetic occurrence");
  foreach(var (op,value,expected) in new[]{("add",2L,"a012.jpg"),("multiply",3L,"a030.jpg"),("divide",3L,"a003.jpg"),("set",12345L,"a12345.jpg")})Check(RenamePlan.Apply("a010.jpg",[Rule("number-change") with{NumberOperation=op,NumberValue=value}],0)==expected,"operation "+op);
  Reject(()=>Name(Rule("number-change") with{NumberOperation="divide",NumberValue=0}),"divide0");Reject(()=>RenamePlan.Apply("a9223372036854775807.jpg",[Rule("number-change")],0),"arithmetic overflow");Check(RenamePlan.Apply("a10_b20.jpg",[Rule("number-remove") with{Occurrence="nth",MatchNumber=2}],0)=="a10_b.jpg","remove numbers selected");
  Check(Name(Rule("number-set") with{Prefix="[",Suffix="]",Padding=0})=="[1].jpg","prefix/suffix/no padding");
  Check(RenamePlan.Apply("old.jpg",[Rule("name-list") with{Text="one\ntwo",Part="entire"}],1)=="two","ordered list whole name");Check(RenamePlan.Apply("old.jpg",[Rule("name-list") with{Text="old.jpg\tnew.png",Part="entire"}],0,k=>k=="FileName"?"old.jpg":null)=="new.png","explicit list mapping");Reject(()=>RenamePlan.ParseRules(JsonSerializer.Serialize(Rule("name-list") with{Text="a\tx\na\ty"})),"duplicate mapping rejected");
  foreach(var rule in new[]{Rule("roman-set") with{Counter=1},Rule("alphabet-set") with{Counter=1},Rule("number-set") with{Counter=11},Rule("number-set") with{Counter=1,Step=0},Rule("number-set") with{Counter=1,Start=-1}})Reject(()=>RenamePlan.ParseRules(JsonSerializer.Serialize(rule)),"persistent counter constraints");Reject(()=>RenamePlan.ParseRules(JsonSerializer.Serialize(Rule("number-set") with{Counter=1})+"\n"+JsonSerializer.Serialize(Rule("number-end") with{Counter=1})),"duplicate persistent slots");
  var output=Environment.GetEnvironmentVariable("PHOTOTRAIL_TEST_OUTPUT")??throw new Exception("Missing output");var root=Path.Combine(output,"sequence-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var source=Path.Combine(root,"a.jpg");var xmp=Path.ChangeExtension(source,".xmp");File.WriteAllText(source,"synthetic-main");File.WriteAllText(xmp,"synthetic-xmp");
  var groups=new Dictionary<string,string>{{source,"one"},{xmp,"one"}};var proposed=new[]{new RenameFile(source,Path.Combine(root,"new.jpg"),""),new RenameFile(xmp,Path.Combine(root,"new.xmp"),"")};File.WriteAllText(Path.Combine(root,"new.jpg"),"external-owner");
  var resolved=RenameConflicts.Resolve(proposed,groups,new(){Conflict="numbers"});Check(resolved.Select(f=>f.NewName).SequenceEqual(new[]{"new_001.jpg","new_001.xmp"}),"group numeric collision suffix");Check(File.ReadAllText(Path.Combine(root,"new.jpg"))=="external-owner","no collision overwrite");
  resolved=RenameConflicts.Resolve(proposed,groups,new(){Conflict="letters",LetterSuffixFormat="parentheses"});Check(resolved.All(f=>f.NewName.StartsWith("new(A)",StringComparison.Ordinal)),"group alphabet suffix");Reject(()=>RenameConflicts.Resolve(proposed,groups,new()),"stop collision");
  foreach(var (format,tail) in new[]{("plain","001"),("underscore","_001"),("dash","-001"),("parentheses","(001)")}){resolved=RenameConflicts.Resolve([new(source,Path.Combine(root,"unique.jpg"),"")],groups,new(){Conflict="numbers",KeepFirst=false,NumberSuffixFormat=format});Check(resolved[0].NewName=="unique"+tail+".jpg","suffix format "+format);}
  var overflow=new string('a',251)+".jpg";Reject(()=>RenameConflicts.Resolve([new(source,Path.Combine(root,overflow),"")],groups,new(){Conflict="numbers",KeepFirst=false}),"suffix length refused");
  var counters=Path.Combine(root,"counters.json");Environment.SetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS",counters);var snapshot=RenameCounters.Read(counters);Check(snapshot.Values.Count==10&&snapshot.Values[1]==1&&!File.Exists(counters),"missing preview counters readonly default");var repeat=RenameCounters.Read(counters);Check(repeat==snapshot||repeat.Revision==snapshot.Revision&&repeat.Values.SequenceEqual(snapshot.Values),"preview no advance");
  var plan=await RenamePlan.BuildTargetsAsync([(source,"n001.jpg")]);plan=plan with{CounterUse=new(snapshot,new Dictionary<int,long>{{1,2}})};
  using(var busy=new FileStream(counters+".guard",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){try{await RenameExecutor.ExecuteAsync(plan,Path.Combine(root,"journals"));throw new Exception("concurrent counter allowed");}catch(IOException){Check(File.Exists(source),"crossprocess filelock refuses concurrency");}}
  var result=await RenameExecutor.ExecuteAsync(plan,Path.Combine(root,"journals"));Check(result.Complete&&RenameCounters.Read(counters).Values[1]==2&&!File.Exists(counters+".pending"),"successful confirmed counter commit");var restored=await RenameExecutor.RestoreAsync(result.Journal,Path.Combine(root,"journals"));Check(restored.Complete&&RenameCounters.Read(counters).Values[1]==2,"restore no automatic counter rollback");
  try{await RenameExecutor.ExecuteAsync(plan,Path.Combine(root,"journals"));throw new Exception("stale counter allowed");}catch(IOException){Check(File.Exists(source),"old freeze counter revision refused");}
  snapshot=RenameCounters.Read(counters);plan=await RenamePlan.BuildTargetsAsync([(source,"n002.jpg")]);plan=plan with{CounterUse=new(snapshot,new Dictionary<int,long>{{1,3}})};using(var cancelled=new CancellationTokenSource()){var partial=await RenameExecutor.ExecuteAsync(plan,Path.Combine(root,"journals"),cancelled.Token,(done,total)=>{if(done==1)cancelled.Cancel();});Check(!partial.Complete&&File.Exists(counters+".pending"),"partial cancel retains unknown counter marker");Reject(()=>RenameCounters.Read(counters),"restart counter unknown refused");Reject(()=>InplaceHistory.RequireClear([source]),"persistent unknown blocks metadata writes");var recovery=await RenameExecutor.RestoreAsync(partial.Journal,Path.Combine(root,"journals"));Check(recovery.Complete&&!File.Exists(counters+".pending")&&RenameCounters.Read(counters).Values[1]==2,"explicit verified recovery clears marker no advance");}
  RenameCounters.Reset(counters,[Rule("number-set") with{Counter=1,Start=12}]);Check(RenameCounters.Read(counters).Values[1]==12,"explicit slot reset");
  var scheme=new RenameScheme(Guid.NewGuid(),"跨平台序号",JsonSerializer.Serialize(Rule("number-set") with{Counter=1,Start=7,Step=2,Padding=4}),new RenameOrderSettings("input"){Conflict="numbers"},"0007.jpg");
  var windows=RenameSchemeLibrary.Import(RenameSchemeLibrary.Export(scheme),"import");Check(windows.Rules==scheme.Rules&&windows.Order==scheme.Order,"Windowsv3 roundtrip parameters");
  var mac=MacRenamePreset.Export(scheme);var mapped=RenameSchemeLibrary.Import(mac,"Mac");Check(RenamePlan.Apply("old.jpg",RenamePlan.ParseRules(mapped.Rules),2)=="0011.jpg"&&mapped.Order==scheme.Order,"fixed Macv1 mapped roundtrip");
  Check(mac.Contains("\"value\":\"\""),"Mac filter uses fixed source value field");
  Reject(()=>RenameSchemeLibrary.Import(mac.Replace("\"action\":46","\"action\":95"),"unsupported"),"unsupported Mac action whole reject");
  Reject(()=>RenameSchemeLibrary.Import(mac.Replace("\"value\":\"\"","\"value\":\"filter\""),"filter"),"Mac nondefault filter whole reject");
  Reject(()=>MacRenamePreset.Export(scheme with{Rules=JsonSerializer.Serialize(Rule("regex-replace") with{Text="old",Replacement="new"})}),"unsupported Mac export no guessed action");
  var raw=RenameRulesPreset.Decode(RenameRulesPreset.Encode(scheme.Rules,false,scheme.Order));Check(raw.Rules==scheme.Rules&&raw.Order==scheme.Order,"v3 raw rule settings roundtrip");
  Reject(()=>RenameSchemeLibrary.Import(RenameSchemeLibrary.Export(scheme).Replace("\"version\":3","\"version\":2"),"old"),"advanced not misread as v2");
  var old="{\"version\":1,\"rules\":\"prefix|legacy_\",\"sortByName\":false}";Check(RenameSchemeLibrary.Import(old,"old").Order.Conflict=="stop","old format preserves stop setting");
  var lib=Path.Combine(root,"schemes.json");var opened=RenameSchemeLibrary.Open(lib);var updated=RenameSchemeLibrary.Save(lib,opened,opened.State with{Schemes=opened.State.Schemes.Append(scheme).ToArray(),LastId=scheme.Id});Check(RenameSchemeLibrary.Open(lib).State.LastId==scheme.Id&&updated.State.Version==2,"library restart final identity and migrated version");
  Console.WriteLine($"{count} R08b sequence/conflict/counter safety assertions passed.");
 }
}
